/*
 * Standalone TPC-H supplier join and nation aggregation experiment.
 * Input files contain the raw .tbl rows generated by dbgen.
 * Build with nvcc -O3 -std=c++17 -arch=sm_80 bench/fused_supplier.cu
 * The result is published on stdout and timing CSV is written to stderr.
 */
#include <cuda_runtime.h>
#include <array>
#include <charconv>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <cstdio>
#include <fstream>
#include <stdexcept>
#include <string>
#include <vector>

namespace {

constexpr int nations = 25;
using Clock = std::chrono::steady_clock;
using Total = unsigned long long;

struct Fact {
    uint32_t supplier;
    uint32_t line;
};

struct Group {
    Total count;
    Total sum;

    bool operator==(const Group &other) const
    {
        return count == other.count && sum == other.sum;
    }
};

using Groups = std::array<Group, nations>;

double elapsed_ms(Clock::time_point start)
{
    return std::chrono::duration<double, std::milli>(Clock::now() - start).count();
}

std::ifstream open_input(const std::string &path)
{
    std::ifstream input(path);
    if (!input)
        throw std::runtime_error("cannot open " + path);
    return input;
}

size_t next_column(const std::string &row, size_t start)
{
    size_t end = row.find('|', start);
    if (end == std::string::npos)
        throw std::runtime_error("missing column separator in TPC-H row");
    return end + 1;
}

uint32_t integer_column(const std::string &row, size_t start, size_t next)
{
    uint32_t value;
    const char *end = row.data() + next - 1;
    auto parsed = std::from_chars(row.data() + start, end, value);
    if (parsed.ec != std::errc{} || parsed.ptr != end)
        throw std::runtime_error("invalid integer in TPC-H row");
    return value;
}

std::vector<int8_t> load_supplier(const std::string &directory)
{
    std::ifstream input = open_input(directory + "/supplier.tbl");
    std::vector<int8_t> by_supplier(1, -1);
    std::string row;
    while (std::getline(input, row)) {
        size_t name_column = next_column(row, 0);
        size_t address_column = next_column(row, name_column);
        size_t nation_column = next_column(row, address_column);
        uint32_t supplier = integer_column(row, 0, name_column);
        uint32_t nation = integer_column(row, nation_column, next_column(row, nation_column));
        if (supplier == 0 || supplier >= (uint32_t{1} << 26) || nation >= nations)
            throw std::runtime_error("supplier or nation key is outside the prototype's range");
        if (supplier >= by_supplier.size())
            by_supplier.resize(supplier + 1, -1);
        if (by_supplier[supplier] >= 0)
            throw std::runtime_error("duplicate supplier key");
        by_supplier[supplier] = static_cast<int8_t>(nation);
    }
    if (!input.eof())
        throw std::runtime_error("failed while reading supplier.tbl");
    return by_supplier;
}

std::vector<Fact> load_lineitem(const std::string &directory)
{
    std::ifstream input = open_input(directory + "/lineitem.tbl");
    std::vector<Fact> facts;
    std::string row;
    while (std::getline(input, row)) {
        size_t part_column = next_column(row, 0);
        size_t supplier_column = next_column(row, part_column);
        size_t line_column = next_column(row, supplier_column);
        uint32_t supplier = integer_column(row, supplier_column, line_column);
        uint32_t line = integer_column(row, line_column, next_column(row, line_column));
        if (line < 1 || line > 7)
            throw std::runtime_error("line numbers must be in the TPC-H range 1..7");
        facts.push_back(Fact{supplier, line});
    }
    if (!input.eof())
        throw std::runtime_error("failed while reading lineitem.tbl");
    return facts;
}

Groups aggregate_cpu(const std::vector<int8_t> &by_supplier, const std::vector<Fact> &facts)
{
    Groups groups{};
    for (const Fact &fact : facts) {
        if (fact.supplier < by_supplier.size()) {
            int nation = by_supplier[fact.supplier];
            if (nation >= 0) {
                groups[nation].count++;
                groups[nation].sum += fact.line;
            }
        }
    }
    return groups;
}

constexpr int block_threads = 256;
constexpr int warps = block_threads / 32;
constexpr int facts_per_block = block_threads * 8;

__global__ void aggregate_gpu(const int8_t *by_supplier, size_t supplier_slots,
                              const Fact *facts, size_t rows, Group *groups)
{
    /* Warp-private histograms reduce contention on the 25 nation bins.
     * Each block processes at most 2,048 rows with line numbers in 1..7. */
    __shared__ unsigned int count[warps][nations];
    __shared__ unsigned int sum[warps][nations];
    if (threadIdx.x < warps * nations) {
        count[threadIdx.x / nations][threadIdx.x % nations] = 0;
        sum[threadIdx.x / nations][threadIdx.x % nations] = 0;
    }
    __syncthreads();

    const size_t begin = (size_t) blockIdx.x * facts_per_block;
    const int warp = threadIdx.x / 32;
    for (size_t offset = threadIdx.x; offset < facts_per_block; offset += block_threads) {
        if (begin + offset < rows) {
            Fact fact = facts[begin + offset];
            int nation = fact.supplier < supplier_slots ? by_supplier[fact.supplier] : -1;
            if (nation >= 0) {
                atomicAdd(&count[warp][nation], 1U);
                atomicAdd(&sum[warp][nation], fact.line);
            }
        }
    }
    __syncthreads();

    if (threadIdx.x < nations) {
        unsigned int nation = threadIdx.x;
        Total total_count = 0;
        Total total_sum = 0;
        for (int w = 0; w < warps; w++) {
            total_count += count[w][nation];
            total_sum += sum[w][nation];
        }
        if (total_count > 0) {
            atomicAdd(&groups[nation].count, total_count);
            atomicAdd(&groups[nation].sum, total_sum);
        }
    }
}

void check(cudaError_t status, const char *operation)
{
    if (status != cudaSuccess)
        throw std::runtime_error(std::string(operation) + ": " + cudaGetErrorString(status));
}

struct GpuTiming {
    double total;
    double h2d;
    double clear;
    double kernel;
    double d2h;
};

struct FusedGpu {
    cudaStream_t stream = nullptr;
    cudaEvent_t events[5]{};
    int8_t *by_supplier = nullptr;
    Fact *facts = nullptr;
    Group *groups = nullptr;
    Groups result{};

    FusedGpu() = default;
    FusedGpu(const FusedGpu &) = delete;
    FusedGpu &operator=(const FusedGpu &) = delete;

    ~FusedGpu()
    {
        if (stream)
            cudaStreamSynchronize(stream);
        for (auto event : events) {
            if (event)
                cudaEventDestroy(event);
        }
        if (groups)
            cudaFree(groups);
        if (facts)
            cudaFree(facts);
        if (by_supplier)
            cudaFree(by_supplier);
        if (stream)
            cudaStreamDestroy(stream);
    }

    void initialize(const std::vector<int8_t> &dimension, size_t rows)
    {
        check(cudaSetDevice(0), "select device");
        check(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking), "create stream");
        for (auto &event : events)
            check(cudaEventCreate(&event), "create event");
        check(cudaMalloc(&by_supplier, dimension.size() * sizeof(int8_t)), "allocate supplier lookup");
        if (rows)
            check(cudaMalloc(&facts, rows * sizeof(Fact)), "allocate projected lineitem");
        check(cudaMalloc(&groups, sizeof(result)), "allocate 25 group results");
        check(cudaMemcpyAsync(by_supplier, dimension.data(), dimension.size() * sizeof(int8_t),
                              cudaMemcpyHostToDevice, stream), "upload supplier lookup");
        check(cudaStreamSynchronize(stream), "finish supplier upload");
    }

    void record(int i)
    {
        check(cudaEventRecord(events[i], stream), "record event");
    }

    double time_ms(int first, int last)
    {
        float ms = 0;
        check(cudaEventElapsedTime(&ms, events[first], events[last]), "measure event");
        return ms;
    }

    GpuTiming run(size_t supplier_slots, const std::vector<Fact> &input)
    {
        auto start = Clock::now();
        record(0);
        if (!input.empty())
            check(cudaMemcpyAsync(facts, input.data(), input.size() * sizeof(Fact),
                                  cudaMemcpyHostToDevice, stream), "upload lineitem");
        record(1);
        check(cudaMemsetAsync(groups, 0, sizeof(result), stream), "clear group results");
        record(2);
        if (!input.empty()) {
            const size_t blocks = (input.size() + facts_per_block - 1) / facts_per_block;
            if (blocks > 2147483647)
                throw std::runtime_error("fact input exceeds the kernel grid limit");
            aggregate_gpu<<<static_cast<unsigned int>(blocks), block_threads, 0, stream>>>(
                by_supplier, supplier_slots, facts, input.size(), groups);
            check(cudaGetLastError(), "launch fused join and aggregation");
        }
        record(3);
        check(cudaMemcpyAsync(result.data(), groups, sizeof(result),
                              cudaMemcpyDeviceToHost, stream), "read 25 group results");
        record(4);
        check(cudaEventSynchronize(events[4]), "finish fused execution");
        return {elapsed_ms(start), time_ms(0, 1), time_ms(1, 2), time_ms(2, 3), time_ms(3, 4)};
    }
};

void print_groups(const Groups &groups)
{
    /* Match psql -qAt output for the native GROUP BY ordered by nation key. */
    for (int nation = 0; nation < nations; nation++) {
        if (groups[nation].count)
            std::printf("%d|%llu|%llu\n", nation, groups[nation].count, groups[nation].sum);
    }
}

} // namespace

int main(int argc, char **argv)
{
    if (argc < 2 || argc > 3) {
        std::fprintf(stderr, "usage: %s TPC_H_DATA_DIRECTORY [TRIALS]\n", argv[0]);
        return 2;
    }
    try {
        int trials = 7;
        if (argc == 3) {
            const char *end = argv[2] + std::strlen(argv[2]);
            auto parsed = std::from_chars(argv[2], end, trials);
            if (parsed.ec != std::errc{} || parsed.ptr != end || trials < 1 || trials > 100)
                throw std::runtime_error("trials must be an integer between 1 and 100");
        }

        auto start = Clock::now();
        auto by_supplier = load_supplier(argv[1]);
        double supplier_ms = elapsed_ms(start);

        start = Clock::now();
        auto facts = load_lineitem(argv[1]);
        double lineitem_ms = elapsed_ms(start);

        auto expected = aggregate_cpu(by_supplier, facts);
        FusedGpu gpu;
        start = Clock::now();
        gpu.initialize(by_supplier, facts.size());
        double setup_ms = elapsed_ms(start);
        gpu.run(by_supplier.size(), facts);
        if (gpu.result != expected)
            throw std::runtime_error("warmup GPU groups differ from the CPU reference");

        std::fprintf(stderr,
            "trial,rows,supplier_parse_ms,lineitem_parse_ms,gpu_setup_ms,cpu_ms,gpu_wall_ms,"
            "input_h2d_ms,clear_ms,kernel_ms,result_d2h_ms,dimension_h2d_bytes,input_h2d_bytes,"
            "result_d2h_bytes\n");
        for (int trial = 1; trial <= trials; trial++) {
            start = Clock::now();
            auto groups = aggregate_cpu(by_supplier, facts);
            double cpu_ms = elapsed_ms(start);

            GpuTiming timing = gpu.run(by_supplier.size(), facts);
            if (gpu.result != groups)
                throw std::runtime_error("GPU groups differ from the CPU reference");

            std::fprintf(stderr,
                "%d,%zu,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%zu,%zu,%zu\n",
                trial, facts.size(), supplier_ms, lineitem_ms, setup_ms, cpu_ms,
                timing.total, timing.h2d, timing.clear, timing.kernel, timing.d2h,
                by_supplier.size() * sizeof(int8_t), facts.size() * sizeof(Fact),
                sizeof(gpu.result));
        }
        print_groups(gpu.result);
        return 0;
    } catch (const std::exception &ex) {
        std::fprintf(stderr, "%s\n", ex.what());
        return 1;
    }
}
